#!/bin/sh
# GENERATED by validation/stanford/make_decks.py
# Runs every stanford-1 deck with Spectre; results land next to each deck.
# A failing deck is reported and the rest still run.  The two 8.1 ms
# HSPICE-template DC decks (1 us step bound) run last: they are the most
# likely to hit Spectre step-control trouble on the RESET slide.
cd "$(dirname "$0")"
failed=''
spectre +escchars -format psfascii -raw pulse_reset_ref.raw +log pulse_reset_ref.log pulse_reset_ref.scs || failed="$failed pulse_reset_ref"
spectre +escchars -format psfascii -raw pulse_set_ref.raw +log pulse_set_ref.log pulse_set_ref.scs || failed="$failed pulse_set_ref"
spectre +escchars -format psfascii -raw dc_loop.raw +log dc_loop.log dc_loop.scs || failed="$failed dc_loop"
spectre +escchars -format psfascii -raw reset_train.raw +log reset_train.log reset_train.scs || failed="$failed reset_train"
spectre +escchars -format psfascii -raw set_train.raw +log set_train.log set_train.scs || failed="$failed set_train"
spectre +escchars -format psfascii -raw pulse_width_sweep.raw +log pulse_width_sweep.log pulse_width_sweep.scs || failed="$failed pulse_width_sweep"
spectre +escchars -format psfascii -raw amplitude_sweep.raw +log amplitude_sweep.log amplitude_sweep.scs || failed="$failed amplitude_sweep"
spectre +escchars -format psfascii -raw read_disturb_hold.raw +log read_disturb_hold.log read_disturb_hold.scs || failed="$failed read_disturb_hold"
spectre +escchars -format psfascii -raw s1_pm1p3.raw +log s1_pm1p3.log s1_pm1p3.scs || failed="$failed s1_pm1p3"
spectre +escchars -format psfascii -raw s1_pm1p4.raw +log s1_pm1p4.log s1_pm1p4.scs || failed="$failed s1_pm1p4"
spectre +escchars -format psfascii -raw dc_reset_ref.raw +log dc_reset_ref.log dc_reset_ref.scs || failed="$failed dc_reset_ref"
spectre +escchars -format psfascii -raw dc_set_ref.raw +log dc_set_ref.log dc_set_ref.scs || failed="$failed dc_set_ref"
[ -z "$failed" ] || { echo "FAILED decks:$failed"; exit 1; }
